INSERT INTO "survey_answers" ("id","survey_response_id","survey_question_id","option_id","other_text","numeric_value","text_value","created_at","updated_at") VALUES('9510313d-0a20-44d9-88e2-f72f2a726737','a426f928-8580-4e67-bb4a-32d6a3347eda','a2000000-0000-4000-8000-000000000010',NULL,NULL,NULL,'Saya sebagai IRT yang buta dunia wirausaha produk dengan ini sangat berterima kasih sekali sudah di berikan pelatihan ini, membuat mata saya terbuka dan ilmu yang sangat baru belum saya pelajari sebelumnya membuat saya semakin semangat untuk menjadi wirausaha produk semakin sukses.. saya sangat berharap saya tidak hanya mendapatkan pelatihan tidak hanya di kesempatan ini.. tapi ingin mendapatkan banyak pelatihan2 lagi untuk menambah ilmu pengetahuan dan upgret diri saya yang bekecimpung di dunia usaha kuliner.. banyak masalah usaha yang  harus di pecahkan, ketika ada pelatihan seperti ini membuka mata banyak solusi dan pemecahan masalah usaha sendiri, sangat berhapat terus bisa ikut di pelatihan2 berikut nya 🙏','2026-10-15 13:18:57','2026-10-15 13:18:57');
