INSERT INTO "survey_answers" ("id","survey_response_id","survey_question_id","option_id","other_text","numeric_value","text_value","created_at","updated_at") VALUES('87d39f75-a354-4fc1-8e92-bd3f8c88264b','456de0bc-3422-43fa-8803-4ae068a10d16','a2000000-0000-4000-8000-000000000021',NULL,NULL,NULL,replace('Mohon izin sebelumnya bapak / ibu,saya berharap berkomitmen sebelum nya untuk mengikuti Diklat di BDI😍, jujur sebelum nya BPK/ ibu, saya seorang single mom yang sedang berjuang dan berkembang dalam usaha yang sudah saya jalan nya sejak tahun 2021 dan NIB nya di urus tahun2022, jujur bapak/ibu sebenar nya usaha ini fokus utama sama mencari nafkah, namun dlm proses byk nya rintangan tetap saya jalankan, meskipun pelan. Dan sy berusaha ada kegiatan lain/ cari nafkah yg lain sy lakukan untuk modal tambahan usaha saya, izin permisi kemaren plg LBH dulu di jam 14:30🙏\n\nDan Diklat ini sangat membantu saya, kedepan nya inshaallah usaha saya berkembang dan izin usaha nya SDH lengkap. Aamiin ya allah\nTerimakasih buat bapak/ ibu atas kesempatannya\n\nSalam sehat dan tetap semangat','\n',char(10)),'2026-10-22 02:14:15','2026-10-22 02:14:15');
